-static int find_style(ASS_Track *track, const char *name, int def)
-{
-    for (int n = 0; n < track->n_styles; n++) {
-        if (track->styles[n].Name && strcmp(track->styles[n].Name, name) == 0)
-            return n;
-    }
-    return def;
-}
